\definecolor{deepskyblue}{rgb}{0.173,0.447,0.682}
\definecolor{orangepeel}{rgb}{0.902, 0.624, 0}
\definecolor{lightyellow}{rgb}{0.953,0.882,0.388}
\definecolor{darkgreen}{rgb}{0.271, 0.608, 0.463}
\definecolor{lightblue}{rgb}{0.484,0.702,0.894}
\definecolor{rustred}{rgb}{0.784,0.392,0.149}
\definecolor{fadedpink}{rgb}{0.753,0.494,0.643}

\begin{document}

\pagestyle{empty} %% IMPORTANT

\begin{tikzpicture}[scale = 1.0]
\def\gcolor{deepskyblue}

\begin{axis}[
trig format plots=rad,
legend pos=outer north east,
tick label style={font=\footnotesize},
tick style={line width=0.8pt, color=black},
label style={font=\small},
legend style={font=\footnotesize},
axis line style = thick,
axis y line = center,
axis x line = middle,
xmin = -3.5,
xmax = 3.5,
ymin = -0.1,
ymax = 0.5,
xtick= {-1.5, 1.5},
xticklabels = {$-2.5758$, $2.5758$},
ytick = {10},     
xlabel = $z$,
ylabel = {$f(z)$},
every axis x label/.style={
	at={(ticklabel* cs:1.02)},
	anchor=west,
},
every axis y label/.style={
	at={(ticklabel* cs:1.02)},
	anchor=south,
},
]

\addplot [
domain = -7:7,
samples=200,
color=\gcolor,
line width=1.2pt,
]{1/(2*3.14)^0.5 * 2.71^(-0.5*x^2)};


\begin{scope}
		\addplot [name path=f, domain=1.5:5, samples=100, blue, solid,
			line width=1pt,	smooth]{ 1/(2*3.14)^0.5 * 2.71^(-0.5*x^2) };
		\addplot [name path=g, domain=1.5:5, samples=100,
			draw=none, line width=1pt, smooth]{0};
	    \addplot[blue!40!white, fill opacity=0.5] fill between [of=f and g]; 
	\end{scope}

\begin{scope}
		\addplot [name path=f, domain=-5:-1.5, samples=100, blue, solid,
			line width=1pt,	smooth]{ 1/(2*3.14)^0.5 * 2.71^(-0.5*x^2) };
		\addplot [name path=g, domain=-5:-1.5, samples=100,
			draw=none, line width=1pt, smooth]{0};
	    \addplot[blue!40!white, fill opacity=0.5] fill between [of=f and g]; 
	\end{scope}

\node[black] at (axis cs: 2.5,0.25) {$0.005$};
\draw[-latex, black] (axis cs: 2.5,0.225) -- (axis cs: -1.65,0.05);
\draw[-latex, black] (axis cs: 2.5,0.225) -- (axis cs: 1.65,0.05);


\end{axis}
\end{tikzpicture}
\end{document}

